namespace JuiceFresh.Scripts
{
    public static class LevelProgressionHelper
    {
        // Levels 1-45: base chapter, 46-90: North chapter (generated by ArtSource/Levels/gen_north_levels.py).
        public const int LastLevel = 90;

        // After the last level the game replays LoopStart..LastLevel in a cycle.
        private const int LoopStart = 20;

        public static int CalculateLevel(int playerLevel)
        {
            if (playerLevel <= LastLevel)
                return playerLevel;

            int loopLength = LastLevel - LoopStart + 1;
            return LoopStart + (playerLevel - LastLevel - 1) % loopLength;
        }
    }
}
